    &lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Des-Objets-Magiques.html&quot; title=&quot;Descriptions des objets magiques&quot;&gt;format&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Relatives-Aux-Objets-Magiques.html&quot; title=&quot;R&#232;gles relatives aux objets magiques&quot;&gt;fonctionnement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Dobjets-Magiques.html&quot; title=&quot;Cr&#233;ation d&amp;#39;objets magiques&quot;&gt;cr&#233;ation&lt;/a&gt;&lt;/li&gt;
