&lt;/div&gt;
Ces objets sont des chapeaux, des diad&#232;mes, des couronnes, des aur&#233;oles, des couvre-chefs, des casques, des capuches, des lauriers, des masques, des voiles, des perruques et tous les objets que l’on porte sur la t&#234;te mais pas sur le front.&lt;br /&gt;&lt;br /&gt;Tout le monde peut utiliser un objet merveilleux port&#233; sur la t&#234;te &#224; moins que le contraire ne soit indiqu&#233; dans sa description. Ces objets sont habituellement activ&#233;s par usage ou par un mot de commande mais il y a parfois des diff&#233;rences en fonction des objets.&lt;br /&gt;&lt;br /&gt;Tous les objets merveilleux d&#233;crits ci-dessous p&#232;sent entre 0 g et 2,5 kg.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
&lt;table CLASS=&quot;tablo centre autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Objets merveilleux port&#233;s sur la t&#234;te&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Objet&lt;/td&gt;&lt;td WIDTH= &quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;65%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-De-Changement-Rapide.html&quot; title=&quot;Masque de changement rapide&quot;&gt;Masque de changement rapide&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;d&#233;guisement&lt;/a&gt;&lt;/i&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; &#224; volont&#233;. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Justicier.html&quot; title=&quot;Le justicier&quot;&gt;justicier&lt;/a&gt; peut changer d&#39;identit&#233; par une action de mouvement. Lorsqu&#39;il est utilis&#233;, permet au porteur de cr&#233;er une diversion. Usage unique.&lt;/td&gt;&lt;td&gt;650 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couvre-Chef-De-D&#233;guisement-Humano&#239;de.html&quot; title=&quot;Couvre-chef de d&#233;guisement humano&#239;de&quot;&gt;Couvre-chef de d&#233;guisement humano&#239;de&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;d&#233;guisement&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;, mais permet uniquement de prendre l’apparence d’une cr&#233;ature de taille P. Se fond mal dans le d&#233;guisement.&lt;/td&gt;&lt;td&gt;800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Calotte-De-Lumi&#232;re.html&quot; title=&quot;Calotte de lumi&#232;re&quot;&gt;Calotte de lumi&#232;re&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Manifeste les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re.html&quot; title=&quot;Lumi&#232;re&quot;&gt;lumi&#232;re&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Plume-De-Panache.html&quot; title=&quot;Plume de panache&quot;&gt;Plume de panache&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, un &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur.html&quot; title=&quot;Le bretteur&quot;&gt;bretteur&lt;/a&gt; qui accomplit un &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur.html#EXPLOITS&quot; title=&quot;Le bretteur&quot;&gt;exploit&lt;/a&gt; obtient un point de &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur#Panache.html&quot; title=&quot;panache&quot;&gt;panache&lt;/a&gt; qu’il peut d&#233;penser pour le r&#233;aliser.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faux-Visage.html&quot; title=&quot;Faux visage&quot;&gt;Faux visage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Donne l’apparence d’un humano&#239;de de taille P ou M sp&#233;cifique (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;d&#233;guisement&lt;/a&gt;&lt;/i&gt;) choisi &#224; la fabrication.&lt;/td&gt;&lt;td&gt;1 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bicorne-De-Besmara.html&quot; title=&quot;Bicorne de Besmara&quot;&gt;Bicorne de Besmara&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; et d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt;. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Besmara-(Technique).html&quot; title=&quot;Besmara&quot;&gt;Besmara&lt;/a&gt; peut flotter &#224; la surface de l&#39;eau (et s&#39;y d&#233;placer &#224; une vitesse de 9 m) &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;1 700 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couvre-Chef-De-D&#233;guisement.html&quot; title=&quot;Couvre-chef de d&#233;guisement&quot;&gt;Couvre-chef de d&#233;guisement&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;d&#233;guisement&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;. Peut changer d’apparence dans le d&#233;guisement.&lt;/td&gt;&lt;td&gt;1 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couvre-Chef-Amortissant.html&quot; title=&quot;Couvre-chef amortissant&quot;&gt;Couvre-chef amortissant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut changer les d&#233;g&#226;ts d’un coup critique en d&#233;g&#226;ts non-l&#233;taux.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-Sacr&#233;-Du-Dieu-Vivant.html&quot; title=&quot;Masque sacr&#233; du dieu vivant&quot;&gt;Masque sacr&#233; du dieu vivant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un suivant de Razmir b&#233;n&#233;ficie d&#39;un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt; et d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;, et lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Terreur.html&quot; title=&quot;Terreur&quot;&gt;terreur&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soins-L&#233;gers.html&quot; title=&quot;Soins l&#233;gers&quot;&gt;soins l&#233;gers&lt;/a&gt;&lt;/i&gt; une fois par jour.&lt;/td&gt;&lt;td&gt;2 100 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couvre-Chef-Du-Vieux-Parieur.html&quot; title=&quot;Couvre-chef du vieux parieur&quot;&gt;Couvre-chef du vieux parieur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couvre-Chef-De-D&#233;guisement.html&quot; title=&quot;Couvre-chef de d&#233;guisement&quot;&gt;couvre-chef de d&#233;guisement&lt;/a&gt;&lt;/i&gt; (nain uniquement). Augmente de 1 le DD des &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Coercition.html&quot; title=&quot;Coercition&quot;&gt;enchantement (coercition)&lt;/a&gt; du porteur. Trois fois par jour, permet de changer le r&#233;sultat d&#39;un d&#233; de jeu de 1.&lt;/td&gt;&lt;td&gt;2 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;charpe-De-La-Fleur-De-Laube.html&quot; title=&quot;&#201;charpe de la Fleur de l&amp;#39;Aube&quot;&gt;&#201;charpe de la Fleur de l&#39;Aube&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Prot&#232;ge de la chaleur (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Endurance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;Endurance aux &#233;nergies destructives&quot;&gt;endurance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;). Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Feuille-Morte.html&quot; title=&quot;Feuille morte&quot;&gt;feuille morte&lt;/a&gt;&lt;/i&gt;. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Sarenra&#233;-(Technique).html&quot; title=&quot;Sarenra&#233;&quot;&gt;Sarenra&#233;&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soins-L&#233;gers.html&quot; title=&quot;Soins l&#233;gers&quot;&gt;soins l&#233;gers&lt;/a&gt;&lt;/i&gt; une fois par jour (peut &#234;tre d&#233;clench&#233; imm&#233;diatement apr&#232;s &#234;tre tomb&#233; &#224; -1 &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;pv&lt;/a&gt; ou moins), et faire briller cet objet comme une &lt;a class=&quot;pagelink&quot; href=&quot;Torche-(Objet).html&quot; title=&quot;Torche&quot;&gt;torche&lt;/a&gt; qui g&#234;ne les cr&#233;atures sensibles &#224; la lumi&#232;re du soleil.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tricorne-De-Besmara.html&quot; title=&quot;Tricorne de Besmara&quot;&gt;Tricorne de Besmara&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt; (marin). Permet &#224; un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Besmara-(Technique).html&quot; title=&quot;Besmara&quot;&gt;Besmara&lt;/a&gt; de transformer l&#39;objet en petit bateau une fois par jour (pendant 8 heures maximum).&lt;/td&gt;&lt;td&gt;2 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-De-Bal-Diabolique.html&quot; title=&quot;Masque de bal diabolique&quot;&gt;Masque de bal diabolique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couvre-Chef-De-D&#233;guisement.html&quot; title=&quot;Couvre-chef de d&#233;guisement&quot;&gt;couvre-chef de d&#233;guisement&lt;/a&gt;&lt;/i&gt;. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-Personne.html&quot; title=&quot;Charme-personne&quot;&gt;charme-personne&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Diabolique.html&quot; title=&quot;Gu&#233;rison diabolique&quot;&gt;gu&#233;rison diabolique&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;2 900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-De-Lavare.html&quot; title=&quot;Masque de l’avare&quot;&gt;Masque de l’avare&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re l’&lt;a class=&quot;pagelink&quot; href=&quot;Odorat-(Capacit&#233;).html&quot; title=&quot;Odorat (Ext)&quot;&gt;odorat&lt;/a&gt; mais uniquement pour les pi&#232;ces de monnaie et les pierres pr&#233;cieuses, ainsi qu’un bonus de comp&#233;tence de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Estimation.html&quot; title=&quot;Estimation&quot;&gt;Estimation&lt;/a&gt; pour d&#233;terminer la valeur de ces derni&#232;res.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-De-Chair-Tranchante.html&quot; title=&quot;Masque de chair tranchante&quot;&gt;Masque de chair tranchante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +2 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt;. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Zon-Kuthon-(Technique).html&quot; title=&quot;Zon-Kuthon&quot;&gt;Zon-Kuthon&lt;/a&gt; peut infliger 2d4+2 d&#233;g&#226;ts de force &#224; une cr&#233;ature dans un rayon de 30 m autour de lui une fois par jour, et changer la forme de cet objet.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Voile-Des-Voiles.html&quot; title=&quot;Voile des voiles&quot;&gt;Voile des voiles&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;d&#233;guisement&lt;/a&gt;&lt;/i&gt; (l&#39;objet reste visible). Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Sivanah-(Technique).html&quot; title=&quot;Sivanah&quot;&gt;Sivanah&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flou.html&quot; title=&quot;Flou&quot;&gt;flou&lt;/a&gt;&lt;/i&gt; une fois par jour, et b&#233;n&#233;ficie d&#39;un bonus de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;3 300 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chapeau-D&#233;nergie-N&#233;gative.html&quot; title=&quot;Chapeau d&amp;#39;&#233;nergie n&#233;gative&quot;&gt;Chapeau d&#39;&#233;nergie n&#233;gative&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Lorsqu&#39;il commence son tour avec sa langue attach&#233;e &#224; une cr&#233;ature ou en &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt; avec elle, elle subit un malus de -1 en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; et la langue du porteur obtient 5 points de vie temporaire, pendant 1 minute (effets cumulables).&lt;/td&gt;&lt;td&gt;3 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-Du-Traqueur.html&quot; title=&quot;Masque du traqueur&quot;&gt;Masque du traqueur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;. Une fois par jour, permet de se transformer en une cr&#233;ature &#224; 18 m ou moins, conf&#233;rant un bonus de +10 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;D&#233;guisement&lt;/a&gt; pour lui ressembler et de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jets d’attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; des armes contre elle, pendant 1 heure.&lt;/td&gt;&lt;td&gt;3 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-De-La-M&#232;re-D&#233;mone.html&quot; title=&quot;Masque de la m&#232;re d&#233;mone&quot;&gt;Masque de la m&#232;re d&#233;mone&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt;. Permet de sentir les cr&#233;atures proches en chaleur ou fertiles. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Lamashtu-(Technique).html&quot; title=&quot;Lamashtu&quot;&gt;Lamashtu&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres-Ii.html&quot; title=&quot;Convocation de monstres II&quot;&gt;convocation de monstres II&lt;/a&gt;&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Hy&#232;ne.html&quot; title=&quot;Hy&#232;ne&quot;&gt;hy&#232;ne&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types.html#CREATUREFIELONE&quot; title=&quot;Les arch&#233;types&quot;&gt;fi&#233;lonne&lt;/a&gt; uniquement) une fois par jour, procr&#233;er avec des animaux de la m&#234;me cat&#233;gorie de taille que lui, et utiliser cet objet comme &lt;a class=&quot;pagelink&quot; href=&quot;Symbole-Sacr&#233;-(Objet).html&quot; title=&quot;Symbole sacr&#233;&quot;&gt;symbole sacr&#233;&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;3 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-D&#233;nergies-Discordantes.html&quot; title=&quot;Masque d&amp;#39;&#233;nergies discordantes&quot;&gt;Masque d&#39;&#233;nergies discordantes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permet de remplacer les d&#233;g&#226;ts d&#39;&#233;nergie d&#39;un sort du 3e niveau ou moins lanc&#233; par le porteur en leur &#233;l&#233;ment oppos&#233; (feu en froid, acide en &#233;lectricit&#233;, et vice versa).&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serre-T&#234;te-De-Persuasion.html&quot; title=&quot;Serre-t&#234;te de persuasion&quot;&gt;Serre-t&#234;te de persuasion&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +3 aux tests bas&#233;s sur le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;4 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-De-Destruction-Et-De-Cr&#233;ation.html&quot; title=&quot;Masque de destruction et de cr&#233;ation&quot;&gt;Masque de destruction et de cr&#233;ation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;&lt;/i&gt; dans une configuration, et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lecture-De-La-Magie.html&quot; title=&quot;Lecture de la magie&quot;&gt;lecture de la magie&lt;/a&gt;&lt;/i&gt; dans l&#39;autre. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;N&#233;thys-(Technique).html&quot; title=&quot;N&#233;thys&quot;&gt;N&#233;thys&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Projectile-Magique.html&quot; title=&quot;Projectile magique&quot;&gt;projectile magique&lt;/a&gt;&lt;/i&gt; dans une configuration et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;d&#233;guisement&lt;/a&gt;&lt;/i&gt; dans l&#39;autre une fois par jour.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casque-De-Pr&#233;sence-Intimidante.html&quot; title=&quot;Casque de pr&#233;sence intimidante&quot;&gt;Casque de pr&#233;sence intimidante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html&quot; title=&quot;Le barbare&quot;&gt;barbare&lt;/a&gt; obtient le pouvoir de rage &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage.html#REGARDINTIMIDANT&quot; title=&quot;Les pouvoirs de rage du barbare&quot;&gt;regard intimidant&lt;/a&gt; tant qu’il est enrag&#233;.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Jingasa-Du-Soldat-Chanceux.html&quot; title=&quot;Jingasa du soldat chanceux&quot;&gt;Jingasa du soldat chanceux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de parade de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;. Permet d’annuler les d&#233;g&#226;ts d’un coup critique ou d’une attaque sournoise une seule fois.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-Du-Lutteur.html&quot; title=&quot;Masque du lutteur&quot;&gt;Masque du lutteur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet d’effectuer des manœuvres de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#LUTTE&quot; title=&quot;Les manœuvres offensives&quot;&gt;lutte&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#BOUSCULADE&quot; title=&quot;Les manœuvres offensives&quot;&gt;bousculade&lt;/a&gt; sans provoquer d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUEDOPPORTUNITE&quot; title=&quot;Valeurs de combat&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Heaume-De-Compr&#233;hension.html&quot; title=&quot;Heaume de compr&#233;hension&quot;&gt;Heaume de compr&#233;hension&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt; pour d&#233;chiffrer des textes incomplets, anarchiques ou exotiques.&lt;/td&gt;&lt;td&gt;5 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couronne-Des-&#201;p&#233;es.html&quot; title=&quot;Couronne des &#233;p&#233;es&quot;&gt;Couronne des &#233;p&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 fois par jour, lorsque le porteur subit une attaque, peut manifester une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arme-Spirituelle.html&quot; title=&quot;Arme spirituelle&quot;&gt;arme spirituelle&lt;/a&gt;&lt;/i&gt; qui attaque l’assaillant pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; (+1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;/utilisation suppl&#233;mentaire).&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serre-T&#234;te-De-Lumi&#232;re.html&quot; title=&quot;Serre-t&#234;te de lumi&#232;re&quot;&gt;Serre-t&#234;te de lumi&#232;re destructrice&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re-Br&#251;lante.html&quot; title=&quot;Lumi&#232;re br&#251;lante&quot;&gt;lumi&#232;re br&#251;lante&lt;/a&gt;&lt;/i&gt; (3d8).&lt;/td&gt;&lt;td&gt;6 480 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; &lt;a class=&quot;pagelink&quot; href=&quot;Serre-T&#234;te-De-Lumi&#232;re.html&quot; title=&quot;Serre-t&#234;te de lumi&#232;re&quot;&gt;Serre-t&#234;te de Lumi&#232;re D&#233;vastatrice&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Serre-t&#234;te de Lumi&#232;re Destructrice&lt;/i&gt;, mais inflige 5d8 points de d&#233;g&#226;ts sous &lt;a class=&quot;pagelink&quot; href=&quot;Quintessence-Des-Sorts.html&quot; title=&quot;Quintessence des sorts&quot;&gt;Quintessence des sorts&lt;/a&gt;, soit 40 points de d&#233;g&#226;ts.&lt;/td&gt;&lt;td&gt;| 23 760 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-De-Goz.html&quot; title=&quot;Masque de goz&quot;&gt;Masque de goz&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CCMI&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de voir parfaitement &#224; travers la brume, la fum&#233;e ou autres vapeurs opaques. Le porteur est consid&#233;r&#233; comme d&#39;une cat&#233;gorie de taille sup&#233;rieure pour r&#233;sister aux effets du vent, et il b&#233;n&#233;ficie d&#39;un bonus de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; pour r&#233;sister &#224; de tels effets.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-De-La-Mante.html&quot; title=&quot;Masque de la mante&quot;&gt;Masque de la mante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CCMI&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Contient 3 charges quotidiennes. Le porteur peut d&#233;penser une charge pour obtenir la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;vision dans le noir&lt;/a&gt; (18 m), la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Linvisibilit&#233;.html&quot; title=&quot;D&#233;tection de l&amp;#39;invisibilit&#233;&quot;&gt;d&#233;tection de l&#39;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;, la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Perception-De-La-Mort.html&quot; title=&quot;Perception de la mort&quot;&gt;perception de la mort&lt;/a&gt;&lt;/i&gt; ou un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; pendant 30 minutes.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Peinture-De-Guerre-Charmante.html&quot; title=&quot;Peinture de guerre charmante&quot;&gt;Peinture de guerre charmante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut conf&#233;rer les effets de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;B&#233;n&#233;diction.html&quot; title=&quot;B&#233;n&#233;diction&quot;&gt;b&#233;n&#233;diction&lt;/a&gt;&lt;/i&gt; et de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Repli-Exp&#233;ditif.html&quot; title=&quot;Repli exp&#233;ditif&quot;&gt;repli exp&#233;ditif&lt;/a&gt;&lt;/i&gt;, ou d’&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Espoir.html&quot; title=&quot;Espoir&quot;&gt;espoir&lt;/a&gt;&lt;/i&gt; et de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rapidit&#233;.html&quot; title=&quot;Rapidit&#233;&quot;&gt;rapidit&#233;&lt;/a&gt;&lt;/i&gt;, selon l&#39;utilisation de l&#39;objet. Trois utilisations.&lt;/td&gt;&lt;td&gt;6 300 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-Daspect.html&quot; title=&quot;Masque d&amp;#39;aspect&quot;&gt;Masque d’aspect&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peut conf&#233;rer les effets d’un &lt;a class=&quot;pagelink&quot; href=&quot;Chasseur.html#IMITATIONANIMALE&quot; title=&quot;Le chasseur&quot;&gt;aspect animal&lt;/a&gt; du &lt;a class=&quot;pagelink&quot; href=&quot;Chasseur.html&quot; title=&quot;Le chasseur&quot;&gt;chasseur&lt;/a&gt; choisi &#224; la fabrication.&lt;/td&gt;&lt;td&gt;6 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casquette-Denqu&#234;teur-De-Lepidstadt.html&quot; title=&quot;Casquette d&amp;#39;enqu&#234;teur de l&amp;#39;Universit&#233;&quot;&gt;Casquette d’enqu&#234;teur de l’Universit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; pour identifier les monstres. Un enqu&#234;teur qui d&#233;pense une &lt;a class=&quot;pagelink&quot; href=&quot;Enqu&#234;teur.html#INSPIRATION&quot; title=&quot;L&amp;#39;enqu&#234;teur&quot;&gt;inspiration&lt;/a&gt; pour identifier une cr&#233;ature non-humano&#239;de, il peut conserver le r&#233;sultat du d&#233; d’inspiration pendant 1 minute pour l’appliquer &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; ou un test de comp&#233;tence effectu&#233; contre cette cr&#233;ature.&lt;/td&gt;&lt;td&gt;7 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-Du-Krenshar.html&quot; title=&quot;Masque du krenshar&quot;&gt;Masque du krenshar&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Effray&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;effrayer&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Secou&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;secouer&lt;/a&gt; les cr&#233;atures &#224; 30 m ou moins, pendant 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;7 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-Anti-&#201;pid&#233;mie.html&quot; title=&quot;Masque anti-&#233;pid&#233;mie&quot;&gt;Masque anti-&#233;pid&#233;mie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les maladies. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Des-Maladies.html&quot; title=&quot;Gu&#233;rison des maladies&quot;&gt;gu&#233;rison des maladies&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;7 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-De-Lhomme-De-Marbre.html&quot; title=&quot;Masque de l’homme de marbre&quot;&gt;Masque de l’homme de marbre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +10 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; pour mentir et de +5 pour &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales.html#FEINTE&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;feinter&lt;/a&gt;. Inflige un malus de -5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; pour transmettre des messages secrets.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Heaume-Du-Seigneur-Des-Mammouths.html&quot; title=&quot;Heaume du seigneur des mammouths&quot;&gt;Heaume du seigneur des mammouths&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt;, d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#EMPATHIESAUVAGE&quot; title=&quot;Le druide&quot;&gt;empathie sauvage&lt;/a&gt; sur les cr&#233;atures &#233;l&#233;phantines. Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Faune-Ou-De-La-Flore.html&quot; title=&quot;D&#233;tection de la faune ou de la flore&quot;&gt;d&#233;tection de la faune ou de la flore&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communication-Avec-Les-Animaux.html&quot; title=&quot;Communication avec les animaux&quot;&gt;communication avec les animaux&lt;/a&gt;&lt;/i&gt; sur les cr&#233;atures &#233;l&#233;phantines, &#224; volont&#233;. Permet d’effectuer une attaque de d&#233;fense magique infligeant 1d6 points de d&#233;g&#226;ts au corps &#224; corps. Immunise contre le froid (comme avec &lt;a class=&quot;pagelink&quot; href=&quot;Endurance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;Endurance aux &#233;nergies destructives&quot;&gt;endurance aux &#233;nergies destructives&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;8 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Voilette-Des-Regards-Fugaces.html&quot; title=&quot;Voilette des regards fugaces&quot;&gt;Voilette des regards fugaces&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de circonstance de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegardes&lt;/a&gt; contre les illusions visuelles. A 50&#160;% de chance d’immuniser contre les attaques de regard, si le porteur d&#233;tourne les yeux, il peut lancer 2 jets et garder le meilleur r&#233;sultat contre ces attaques.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Anneau-De-Nez-Du-Chasseur.html&quot; title=&quot;Anneau de nez du chasseur&quot;&gt;Anneau de nez du chasseur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; impliquant des odeurs et aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; pour suivre une piste &#224; l&#39;odeur, ainsi que le pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Odorat-(Capacit&#233;).html&quot; title=&quot;Odorat (Ext)&quot;&gt;odorat&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flamme-Du-Bakrakhan.html&quot; title=&quot;Flamme de rage&quot;&gt;Flamme de rage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un porteur en &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGE&quot; title=&quot;Le barbare&quot;&gt;rage&lt;/a&gt; peut en d&#233;penser 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; pour effectuer une attaque de contact &#224; distance infligeant 2d6 points de d&#233;g&#226;ts de feu &#224; une cr&#233;ature &#224; 9m ou moins de lui, ou en d&#233;penser 3 rounds pour manifester une ligne de 18m de long infligeant 5d6 points de d&#233;g&#226;ts de feu.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Heaume-Du-Commandant.html&quot; title=&quot;Heaume du commandant&quot;&gt;Heaume du commandant (inf&#233;rieur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Donne acc&#232;s &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONEQUIPE&quot; title=&quot;Les dons&quot;&gt;don de travail d&#39;&#233;quipe&lt;/a&gt; choisit &#224; la fabrication. Trois fois par jour, permet d&#39;accorder le don associ&#233; aux alli&#233;s &#224; 9 m&#232;tres ou moins pendant 1 minute. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;nain&lt;/a&gt; peut activer le partage de don avec n&#39;importe quel don de travail d&#39;&#233;quipe qu&#39;il poss&#232;de. Le don associ&#233; et/ou partag&#233; ne peut pas d&#233;passer soit une condition de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; de +5 ou moins soit une condition de rangs de comp&#233;tence de 5 ou moins.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Heaume-Du-Commandant.html&quot; title=&quot;Heaume du commandant&quot;&gt;Heaume du commandant (sup&#233;rieur)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;M&#234;mes effets, mais le don associ&#233; et/ou partag&#233; ne peut pas d&#233;passer soit une condition de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; de +10 ou moins soit une condition de rangs de comp&#233;tence de 10 ou moins.&lt;/td&gt;&lt;td&gt;| 16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Heaume-Du-Commandant.html&quot; title=&quot;Heaume du commandant&quot;&gt;Heaume du commandant (supr&#234;me)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;M&#234;mes effets, mais le don associ&#233; et/ou partag&#233; n&#39;a pas de limite de condition.&lt;/td&gt;&lt;td&gt;| 24 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-De-La-M&#233;duse.html&quot; title=&quot;Masque de la m&#233;duse&quot;&gt;Masque de la m&#233;duse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegardes&lt;/a&gt; contre les illusions visuelles et les attaques de regard. Une fois par jour, peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#P&#233;trifi&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;p&#233;trifier&lt;/a&gt; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;P&#233;trification.html&quot; title=&quot;P&#233;trification&quot;&gt;p&#233;trification&lt;/a&gt;&lt;/i&gt;) une cr&#233;ature &#224; 9 m ou moins, pendant 1 minute.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-Encyclop&#233;dique.html&quot; title=&quot;Masque encyclop&#233;dique&quot;&gt;Masque encyclop&#233;dique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Apr&#232;s 10 minutes de port, conf&#232;re un bonus de comp&#233;tence de +10 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (toutes). Occulte la vision du porteur.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cheich-De-Hy&#232;ne.html&quot; title=&quot;Cheich de hy&#232;ne&quot;&gt;Cheich de hy&#232;ne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet d&#39;ignorer les malus li&#233;s aux temp&#234;tes de sable (d&#233;g&#226;ts non l&#233;taux compris). Une fois par jour, peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Effray&#233;.html&quot; title=&quot;Effray&#233;&quot;&gt;effrayer&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secouer&lt;/a&gt; les ennemis dans un rayon de 9 m du porteur et qui peuvent l&#39;entendre.&lt;/td&gt;&lt;td&gt;11 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couvre-Chef-Du-Libre-Penseur.html&quot; title=&quot;Couvre-chef du libre penseur&quot;&gt;Couvre-chef du libre penseur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jet de sauvegarde&lt;/a&gt; suppl&#233;mentaire contre les effets mentaux et de conserver le meilleur r&#233;sultat de ces jets.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Coiffe-Du-Traducteur.html&quot; title=&quot;Coiffe du traducteur&quot;&gt;Coiffe du traducteur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Contient sept plume qui donnent chacune la connaissance d&#39;une langue choisie &#224; la fabrication. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt; peut offrir l&#39;une des plumes &#224; un alli&#233; pour lui donner la connaissance de sa langue associ&#233;e pendant 1 jour avant qu&#39;elle ne tombe en poussi&#232;re.&lt;/td&gt;&lt;td&gt;14 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Calotte-En-Fer-Blanc.html&quot; title=&quot;Calotte en fer blanc&quot;&gt;Calotte en fer blanc&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’intuition de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets mentaux et les divinations visant &#224; en apprendre plus sur le porteur. Inflige un malus de -2 aux valeurs des caract&#233;ristiques mentales et force &#224; effectuer des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; m&#234;me contre les effets inoffensifs.&lt;/td&gt;&lt;td&gt;15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aur&#233;ole-De-S&#233;r&#233;nit&#233;.html&quot; title=&quot;Aur&#233;ole de s&#233;r&#233;nit&#233;&quot;&gt;Aur&#233;ole de s&#233;r&#233;nit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;tieffelin&lt;/a&gt; obtient un bonus de r&#233;sistance de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets du registre des &#233;motions. S’il est d’alignement Bon, il obtient &#233;galement une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la magie (Ext)&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt; de 13 contre les sorts du registre du Mal et un bonus de saintet&#233; de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Heaume-De-La-Valkyrie.html&quot; title=&quot;Heaume de la valkyrie&quot;&gt;Heaume de la valkyrie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet d’invoquer un loup spectral g&#233;ant (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Coursier-Fant&#244;me.html&quot; title=&quot;Coursier fant&#244;me&quot;&gt;coursier fant&#244;me&lt;/a&gt;&lt;/i&gt;, mais avec une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; de 24 et 100 points de vie) pendant 24 heures maximum.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-Dallure-Vol&#233;e.html&quot; title=&quot;Masque d&amp;#39;allure vol&#233;e&quot;&gt;Masque d&#39;allure vol&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois plac&#233; sur le visage d&#39;une cr&#233;ature &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Immobilis&#233;.html&quot; title=&quot;Immobilis&#233;&quot;&gt;immobilis&#233;e&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Mort.html&quot; title=&quot;Mort&quot;&gt;morte&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Sansd&#233;fense.html&quot; title=&quot;Sans d&#233;fense&quot;&gt;sans d&#233;fense&lt;/a&gt;, imite l&#39;apparence de cette cr&#233;ature pendant 24 heures. Le porteur prend l&#39;apparence de la cr&#233;ature imit&#233;e, peut se faire passer pour elle sans malus, conna&#238;t toutes les langues qu&#39;elle conna&#238;t, et consid&#232;re son alignement et ses auras comme &#233;tant celles de la cr&#233;ature imit&#233;e (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Fauss&#233;e.html&quot; title=&quot;D&#233;tection fauss&#233;e&quot;&gt;d&#233;tection fauss&#233;e&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;17 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couronne-Œil-De-Chat.html&quot; title=&quot;Couronne œil-de-chat&quot;&gt;Couronne œil-de-chat&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une pierre pr&#233;cieuse conf&#232;re la &lt;a class=&quot;pagelink&quot; href=&quot;Capacit&#233;s-Sp&#233;ciales.html#VISIONDANSLENOIR&quot; title=&quot;Les capacit&#233;s sp&#233;ciales&quot;&gt;vision dans le noir&lt;/a&gt; (18 m, si le porteur poss&#232;de d&#233;j&#224; cette capacit&#233;, sa port&#233;e augmente de 18 m). La pierre peut &#234;tre d&#233;tach&#233;e pour devenir le capteur magique d’un sort de &lt;a class=&quot;pagelink&quot; href=&quot;Clairaudienceclairvoyance.html&quot; title=&quot;Clairaudience/clairvoyance&quot;&gt;clairaudience/clairvoyance&lt;/a&gt;, que la couronne permet de lancer une fois par jour.&lt;/td&gt;&lt;td&gt;18 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gueule-De-Dragon.html&quot; title=&quot;Gueule de dragon&quot;&gt;Gueule de dragon&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +4 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; et un bonus d’intuition de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre l’aura de pr&#233;sence terrifiante des dragons. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Souffle-De-Dragon.html&quot; title=&quot;Souffle de dragon&quot;&gt;souffle de dragon&lt;/a&gt;&lt;/i&gt;, infligeant 7d6 points de d&#233;g&#226;ts du type d’&#233;nergie d&#233;termin&#233; &#224; la fabrication.&lt;/td&gt;&lt;td&gt;18 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mitre-Du-Hi&#233;rophante.html&quot; title=&quot;Mitre du hi&#233;rophante&quot;&gt;Mitre du hi&#233;rophante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un lanceur de sort divins obtient un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion). Une fois par jour, il peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communion.html&quot; title=&quot;Communion&quot;&gt;communion&lt;/a&gt;&lt;/i&gt; (avec sa divinit&#233; tut&#233;laire) et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;P&#233;nitence.html&quot; title=&quot;P&#233;nitence&quot;&gt;p&#233;nitence&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;18 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couronne-De-Laurier.html&quot; title=&quot;Couronne de laurier&quot;&gt;Couronne de laurier&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de moral de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets mentaux. Lorsque le porteur r&#233;ussit un tel jet, il b&#233;n&#233;ficie d&#39;un bonus de moral de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt;, aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html&quot; title=&quot;Les comp&#233;tences&quot;&gt;comp&#233;tences&lt;/a&gt; et aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jets de d&#233;g&#226;ts&lt;/a&gt; des armes pendant 1 minute. Mais s&#39;il rate un tel jet, il est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secou&#233;&lt;/a&gt; pendant 1 minute. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Mythique.html&quot; title=&quot;mythique&quot;&gt;mythique&lt;/a&gt; gagne 2 &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;pv&lt;/a&gt; temporaires par &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade&lt;/a&gt; qu&#39;il r&#233;cup&#232;re chaque jour et apr&#232;s chaque repos de 8 heures.&lt;/td&gt;&lt;td&gt;19 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chapeau-De-Magicien.html&quot; title=&quot;Chapeau de magicien&quot;&gt;Chapeau de magicien&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permet de d&#233;placer un &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONMETAMAGIE&quot; title=&quot;Les dons&quot;&gt;don de m&#233;tamagie&lt;/a&gt; appliqu&#233; &#224; un sort pr&#233;par&#233; sur un sort en train d’&#234;tre lanc&#233;, et inversement. Ce chapeau n’a aucun effet pour les lanceurs de sorts spontan&#233;s.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diad&#232;me-De-D&#233;tection-De-Pens&#233;es.html&quot; title=&quot;Diad&#232;me de d&#233;tection de pens&#233;es&quot;&gt;Diad&#232;me de d&#233;tection de pens&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re la &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Aveugle-(Capacit&#233;).html&quot; title=&quot;Perception aveugle (Ext)&quot;&gt;perception aveugle&lt;/a&gt; (9 m) mais uniquement pour les cr&#233;atures pourvues d’intelligence (si le porteur poss&#232;de d&#233;j&#224; cette capacit&#233;, il peut diff&#233;rencier lequel de ces sens s’active selon les cr&#233;atures d&#233;tect&#233;es).&lt;/td&gt;&lt;td&gt;22 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-De-La-Camarde.html&quot; title=&quot;Masque de la camarde&quot;&gt;Masque de la camarde&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour apr&#232;s 1 heure de port, peut effectuer une attaque de contact au corps &#224; corps (avec le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; du porteur) sur une cr&#233;ature &#224; 15 m ou moins, infligeant 130 points de d&#233;g&#226;ts (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Doigt-De-Mort.html&quot; title=&quot;Doigt de mort&quot;&gt;doigt de mort&lt;/a&gt;&lt;/i&gt;) ou 3d6+13 si le &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jet de sauvegarde&lt;/a&gt; est r&#233;ussit.&lt;/td&gt;&lt;td&gt;22 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casque-Hurlant.html&quot; title=&quot;Casque hurlant&quot;&gt;Casque hurlant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; sur les cr&#233;atures magiques similaires aux loups. Conf&#232;re les effets du sort &lt;a class=&quot;pagelink&quot; href=&quot;Communication-Avec-Les-Animaux.html&quot; title=&quot;Communication avec les animaux&quot;&gt;communication avec les animaux&lt;/a&gt; sur les canid&#233;s, en permanence. Trois fois par jour, permet de tenter un test d’&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; pour d&#233;moraliser les adversaires &#224; 9 m ou moins, invoquant 1d3 &lt;a class=&quot;pagelink&quot; href=&quot;Loup.html&quot; title=&quot;Loup&quot;&gt;loups&lt;/a&gt; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-Dalli&#233;s-Naturels-Iii.html&quot; title=&quot;Convocation d&amp;#39;alli&#233;s naturels III&quot;&gt;convocation d’alli&#233;s naturels III&lt;/a&gt;&lt;/i&gt;) au d&#233;but du prochain tour du porteur, pendant 5 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;22 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casque-De-Lhomme-Poisson.html&quot; title=&quot;Casque de l&amp;#39;homme-poisson&quot;&gt;Casque de l’homme-poisson&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le porteur voit cinq fois plus loin qu’il ne devrait &#224; cause de l’eau et de la luminosit&#233;, &#224; volont&#233;. Conf&#232;re une vitesse de nage de 9 m ainsi que les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bulle-Dair.html&quot; title=&quot;Bulle d&amp;#39;air&quot;&gt;bulle d’air&lt;/a&gt;&lt;/i&gt;, &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;24 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couronne-De-Conqu&#233;rant.html&quot; title=&quot;Couronne de conqu&#233;rant&quot;&gt;Couronne de conqu&#233;rant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +4 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; et, lorsque le porteur confirme un coup critique, les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pri&#232;re.html&quot; title=&quot;Pri&#232;re&quot;&gt;pri&#232;re&lt;/a&gt;&lt;/i&gt; pendant 5 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. Conf&#232;re des avantages sp&#233;ciaux si le porteur poss&#232;de le don &lt;a class=&quot;pagelink&quot; href=&quot;Prestige.html&quot; title=&quot;Prestige&quot;&gt;Prestige&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;24 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-Dhypnotiseur.html&quot; title=&quot;Masque d&amp;#39;hypnotiseur&quot;&gt;Masque d’hypnotiseur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une &lt;a class=&quot;pagelink&quot; href=&quot;Hypnotiseur.html&quot; title=&quot;L&amp;#39;hypnotiseur&quot;&gt;hypnotiseur&lt;/a&gt; augmente de 3 m la port&#233;e de son &lt;a class=&quot;pagelink&quot; href=&quot;Hypnotiseur.html#REGARDHYPNOTIQUE&quot; title=&quot;L&amp;#39;hypnotiseur&quot;&gt;regard hypnotique&lt;/a&gt; et ce dernier inflige un malus de -2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jets d’attaque&lt;/a&gt; effectu&#233;s contre lui. Une fois par jour, permet d’implanter une &lt;a class=&quot;pagelink&quot; href=&quot;Hypnotiseur.html#INDUCTIONSDHYPNOTISEUR&quot; title=&quot;L&amp;#39;hypnotiseur&quot;&gt;induction d’hypnotiseur&lt;/a&gt; connue sans en d&#233;penser d’utilisation quotidienne, elle ne compte pas dans le nombre d’inductions actives.&lt;/td&gt;&lt;td&gt;25 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casque-Batracien.html&quot; title=&quot;Casque batracien&quot;&gt;Casque batracien&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peut tirer un objet pesant 125 kg ou moins &#224; 6 m ou moins vers le porteur, le porteur peut faire un test de manœuvre pour tirer une cr&#233;ature de la m&#234;me fa&#231;on, ou s’approcher lui-m&#234;me d’un objet trop lourd ou inamovible de la m&#234;me fa&#231;on sans provoquer d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUEDOPPORTUNITE&quot; title=&quot;Valeurs de combat&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;26 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casque-De-T&#233;l&#233;pathie.html&quot; title=&quot;Casque de t&#233;l&#233;pathie&quot;&gt;Casque de t&#233;l&#233;pathie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Pens&#233;es.html&quot; title=&quot;d&#233;tection des pens&#233;es&quot;&gt;d&#233;tection des pens&#233;es&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;, avec la capacit&#233; d’envoyer des messages t&#233;l&#233;pathiques &#224; ses cibles. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Suggestion.html&quot; title=&quot;Suggestion&quot;&gt;suggestion&lt;/a&gt;&lt;/i&gt; &#224; une cible de la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Pens&#233;es.html&quot; title=&quot;d&#233;tection des pens&#233;es&quot;&gt;d&#233;tection des pens&#233;es&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;27 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cagoule-De-Privation-Sensorielle.html&quot; title=&quot;Cagoule de privation sensorielle&quot;&gt;Cagoule de privation sensorielle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme une &lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipement-D’Aventurier---Aventures-Occultes.html#Cagoule de Contention&quot; title=&quot;&#201;quipement d’aventurier - Aventures occultes&quot;&gt;cagoule de contention&lt;/a&gt; et permet au porteur de r&#233;primer les autres modes de perception dont il dispose. Tant qu’il le fait, il peut utiliser l’&lt;a class=&quot;pagelink&quot; href=&quot;Extensions-De-Comp&#233;tences-Occultes.html#&#201;CRITUREAUTOMATIQUE&quot; title=&quot;Extensions de comp&#233;tences occultes&quot;&gt;&#233;criture automatique&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;Extensions-De-Comp&#233;tences-Occultes.html#PSYCHOM&#201;TRIE&quot; title=&quot;Extensions de comp&#233;tences occultes&quot;&gt;psychom&#233;trie&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Extensions-De-Comp&#233;tences-Occultes.html#BAGUETTEDESOURCIER&quot; title=&quot;Extensions de comp&#233;tences occultes&quot;&gt;baguettes de sourcier&lt;/a&gt; m&#234;me s’il ne devrait pas en &#234;tre capable (s’il en est d&#233;j&#224; capable, il obtient un bonus de +5 aux tests de comp&#233;tence associ&#233;s &#224; ces &lt;a class=&quot;pagelink&quot; href=&quot;Extensions-De-Comp&#233;tences-Occultes.html&quot; title=&quot;Extensions de comp&#233;tences occultes&quot;&gt;extensions de comp&#233;tence&lt;/a&gt;). Une fois par jour, permet de poser 5 questions &#224; un esprit ou une entit&#233; psychique proche (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contact-Avec-Les-Plans.html&quot; title=&quot;Contact avec les plans&quot;&gt;contact avec les plans&lt;/a&gt;&lt;/i&gt; mais avec des r&#233;sultats diff&#233;rents).&lt;/td&gt;&lt;td&gt;27 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gage-Des-A&#238;n&#233;s.html&quot; title=&quot;Gage des A&#238;n&#233;s&quot;&gt;Gage des A&#238;n&#233;s&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communion-Avec-La-Nature.html&quot; title=&quot;Communion avec la nature&quot;&gt;communion avec la nature&lt;/a&gt;&lt;/i&gt; (appelant pr&#232;s du porteur un protecteur naturel conscient de ses besoins). Une fois par jour et au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-Monstre.html&quot; title=&quot;Charme-monstre&quot;&gt;charme-monstre&lt;/a&gt;&lt;/i&gt; (plus efficace contre les cr&#233;atures &lt;a class=&quot;pagelink&quot; href=&quot;Type-F&#233;e.html&quot; title=&quot;F&#233;e&quot;&gt;f&#233;eriques&lt;/a&gt;). Au prix d&#39;une utilisation de pouvoir mythique, permet de relancer un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; contre un sort, un pouvoir magique, ou surnaturel lanc&#233; par une cr&#233;ature f&#233;erique avec un bonus de +2.&lt;/td&gt;&lt;td&gt;27 680 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lauriers-De-Commandement.html&quot; title=&quot;Lauriers de commandement&quot;&gt;Lauriers de commandement&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour par cr&#233;ature, peut conf&#233;rer un bonus de moral de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jets d’attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;de sauvegarde&lt;/a&gt; &#224; un alli&#233; &#224; 9 m ou moins (ou au porteur) jusqu’au prochain tour du porteur.&lt;/td&gt;&lt;td&gt;30 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-Mineur-Des-G&#233;ants.html&quot; title=&quot;Masque mineur des g&#233;ants&quot;&gt;Masque mineur des g&#233;ants&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un porteur dot&#233; de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#FORMEANIMALE&quot; title=&quot;Le druide&quot;&gt;forme animale&lt;/a&gt; peut se transformer en certaines cr&#233;atures de sous-type g&#233;ant &#224; la place, obtenant des capacit&#233;s sp&#233;ciales si la forme choisie les poss&#232;des. Tant que le porteur est sous une de ces formes, conf&#232;re un bonus de taille de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; et un bonus d’armure naturelle de +1, tout en infligeant un malus de -1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;30 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; &lt;a class=&quot;pagelink&quot; href=&quot;Masque-Majeur-Des-G&#233;ants.html&quot; title=&quot;Masque majeur des g&#233;ants&quot;&gt;Masque Majeur des G&#233;ants&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Masque Mineur des G&#233;ants&lt;/i&gt;, mais conf&#232;re des capacit&#233;s sp&#233;ciales suppl&#233;mentaires d&#233;pendant de la forme, tout en copiant les immunit&#233;s, les r&#233;sistances et les vuln&#233;rabilit&#233;s de cette forme. Tant que le porteur est sous une de ces formes, conf&#232;re &#224; la place des bonus du &lt;i&gt;Masque Mineur&lt;/i&gt; un bonus de taille de +6 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; et de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt;, ainsi qu’un bonus d’armure naturelle de +4, tout en infligeant un malus de -2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt;. &lt;/td&gt;&lt;td&gt;| 90 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serre-T&#234;te-De-Protection-Des-&#194;mes.html&quot; title=&quot;Serre-t&#234;te de protection des &#226;mes&quot;&gt;Serre-t&#234;te de protection des &#226;mes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Immunise contre les effets qui s’en prennent aux &#226;mes ou qui sont d&#233;jou&#233;s par le sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antid&#233;tection.html&quot; title=&quot;Antid&#233;tection&quot;&gt;antid&#233;tection&lt;/a&gt;&lt;/i&gt;. Emp&#234;che la r&#233;surrection tant qu’il est port&#233; (sauf par les sorts &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Miracle.html&quot; title=&quot;Miracle&quot;&gt;miracle&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Souhait.html&quot; title=&quot;Souhait&quot;&gt;souhait&lt;/a&gt;&lt;/i&gt; ou les interventions divines).&lt;/td&gt;&lt;td&gt;30 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couvre-Chef-De-Volont&#233;-In&#233;branlable.html&quot; title=&quot;Couvre-chef de volont&#233; in&#233;branlable&quot;&gt;Couvre-chef de volont&#233; in&#233;branlable&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 5 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, le porteur est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Confus&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;confus&lt;/a&gt; au lieu d’&#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#H&#233;b&#233;t&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;h&#233;b&#233;t&#233;&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Chancelant&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;chancelant&lt;/a&gt; au lieu d’&#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#&#201;tourdi&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;&#233;tourdi&lt;/a&gt; (les rounds d’activit&#233; de ce pouvoir sont d&#233;compt&#233;s des effets qui ont caus&#233;s son activation).&lt;/td&gt;&lt;td&gt;33 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Heaume-Du-Seigneur-Des-Temp&#234;tes.html&quot; title=&quot;Heaume du seigneur des temp&#234;tes&quot;&gt;Heaume du seigneur des temp&#234;tes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, apr&#232;s 10 minutes de concentration, invoque un orage (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Du-Climat.html&quot; title=&quot;Contr&#244;le du climat&quot;&gt;contr&#244;le du climat&lt;/a&gt;&lt;/i&gt;). Apr&#232;s 10 minutes suppl&#233;mentaires, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Appel-De-La-Foudre.html&quot; title=&quot;Appel de la foudre&quot;&gt;appel de la foudre&lt;/a&gt;&lt;/i&gt; pendant 10 minutes maximum.&lt;/td&gt;&lt;td&gt;35 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casque-De-Cent-Feux.html&quot; title=&quot;Casque de cent feux&quot;&gt;Casque de cent feux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Contient 100 pierres pr&#233;cieuses dont 4 types diff&#233;rents manifestant des effets magiques en rapport avec le feu propres &#224; chaque type. Comme un &lt;a class=&quot;pagelink&quot; href=&quot;Casque-De-Mille-Feux.html&quot; title=&quot;Casque de mille feux&quot;&gt;Casque de Mille Feux&lt;/a&gt;, inflige des d&#233;g&#226;ts aux mort-vivants &#224; 9 m ou moins, conf&#232;re une r&#233;sistance au feu de 20 au porteur et la propri&#233;t&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Feu.html&quot; title=&quot;feu (propri&#233;t&#233;)&quot;&gt;de feu&lt;/a&gt; aux armes qu’il manie. Peut exploser sur le porteur s’il est br&#251;l&#233; par des flammes magiques.&lt;/td&gt;&lt;td&gt;36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Perruque-De-Juge.html&quot; title=&quot;Perruque de juge&quot;&gt;Perruque de juge&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;. Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Mensonge.html&quot; title=&quot;D&#233;tection du mensonge&quot;&gt;d&#233;tection du mensonge&lt;/a&gt;&lt;/i&gt; sur une cr&#233;ature &#224; 9 m ou moins, &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;59 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casque-De-T&#233;l&#233;portation.html&quot; title=&quot;Casque de t&#233;l&#233;portation&quot;&gt;Casque de t&#233;l&#233;portation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;portation.html&quot; title=&quot;T&#233;l&#233;portation&quot;&gt;t&#233;l&#233;portation&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;73 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diad&#232;me-De-L&#233;missaire-Interplan&#233;taire.html&quot; title=&quot;Diad&#232;me de l&amp;#39;&#233;missaire interplan&#233;taire&quot;&gt;Diad&#232;me de l&#39;&#233;missaire interplan&#233;taire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets d&#39;une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adaptation-Plan&#233;taire.html&quot; title=&quot;Adaptation plan&#233;taire&quot;&gt;adaptation plan&#233;taire&lt;/a&gt;&lt;/i&gt; constante. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Lashunta-(Race).html&quot; title=&quot;Les lashuntas&quot;&gt;lashunta&lt;/a&gt; peut communiquer par t&#233;l&#233;pathie avec n&#39;importe quelle cr&#233;ature qui poss&#232;de une langue (qu&#39;il partage une langue avec elle ou non).&lt;/td&gt;&lt;td&gt;67 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aur&#233;ole-De-Menace.html&quot; title=&quot;Aur&#233;ole de menace&quot;&gt;Aur&#233;ole de menace&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Toutes les cr&#233;atures hostiles &#224; 6 m ou moins qui ratent un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jet de sauvegarde&lt;/a&gt; subissent un malus de -2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jets d’attaque&lt;/a&gt; et &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; (ainsi qu’aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt;, s’ils sont d’alignement Chaotique) pendant 24 heures ou jusqu’&#224; ce qu’il infligent des d&#233;g&#226;ts au porteur.&lt;/td&gt;&lt;td&gt;84 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casque-Aveugle.html&quot; title=&quot;Casque aveugle&quot;&gt;Casque aveugle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Rend le porteur &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Aveugl&#233;.html&quot; title=&quot;Aveugl&#233;&quot;&gt;aveugle&lt;/a&gt; mais lui conf&#232;re la &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Aveugle-(Capacit&#233;).html&quot; title=&quot;Perception aveugle (Ext)&quot;&gt;perception aveugle&lt;/a&gt; &#224; 18m. Au prix d&#39;une utlisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, peut conf&#233;rer la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Aveugle-(Capacit&#233;).html&quot; title=&quot;Vision aveugle (Ext)&quot;&gt;vision aveugle&lt;/a&gt; &#224; 18m (&#224; 36m au prix de deux utilisations, ou la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vision-Lucide.html&quot; title=&quot;Vision lucide&quot;&gt;vision lucide&lt;/a&gt;&lt;/i&gt; au prix de trois) pendant 1 minute.&lt;/td&gt;&lt;td&gt;85 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bonnet-Des-R&#234;ves-Sinistres.html&quot; title=&quot;Bonnet des r&#234;ves sinistres&quot;&gt;Bonnet des r&#234;ves sinistres&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le porteur est immunis&#233; contre les cauchemars. Une fois par jour, une porteuse &lt;a class=&quot;pagelink&quot; href=&quot;Changelin-(Race).html&quot; title=&quot;Les changelins&quot;&gt;changelin&lt;/a&gt; peut envoyer un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Cauchemar.html&quot; title=&quot;Cauchemar&quot;&gt;cauchemar&lt;/a&gt;&lt;/i&gt; qui peut imposer une unique &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;diction-Majeure.html&quot; title=&quot;Mal&#233;diction majeure&quot;&gt;mal&#233;diction majeure&lt;/a&gt;&lt;/i&gt; conditionn&#233;e sur un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; rat&#233;. Une fois par jour, peut &#233;mettre un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manteau-De-R&#234;ves.html&quot; title=&quot;Manteau de r&#234;ves&quot;&gt;manteau de r&#234;ves&lt;/a&gt;&lt;/i&gt; qui inflige un &lt;i&gt;cauchemar&lt;/i&gt; &#224; toutes les cr&#233;atures endormies dans la zone d&#39;effet.&lt;/td&gt;&lt;td&gt;90 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Heaume-Du-Roi-Serpent.html&quot; title=&quot;Heaume du roi-serpent&quot;&gt;Heaume du roi-serpent&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-Dalli&#233;s-Naturels-Iii.html&quot; title=&quot;Convocation d&amp;#39;alli&#233;s naturels III&quot;&gt;convocation d&#39;alli&#233;s naturels III&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Empoisonnement.html&quot; title=&quot;Empoisonnement&quot;&gt;empoisonnement&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Iii.html&quot; title=&quot;Forme bestiale III&quot;&gt;forme bestiale III&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hypnose.html&quot; title=&quot;Hypnose&quot;&gt;hypnose&lt;/a&gt;&lt;/i&gt;, et comme pouvoirs magiques. La &lt;i&gt;forme bestiale II&lt;/i&gt; peut &#234;tre am&#233;lior&#233;e au prix d&#39;utilisations de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;96 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casque-D&#233;clat-&#201;lectrique.html&quot; title=&quot;Casque d’&#233;clat &#233;lectrique&quot;&gt;Casque d’&#233;clat &#233;lectrique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Contient 100 pierres pr&#233;cieuses dont 4 types diff&#233;rents manifestant des effets magiques en rapport avec l’&#233;lectricit&#233; propres &#224; chaque type. Comme un &lt;a class=&quot;pagelink&quot; href=&quot;Casque-De-Mille-Feux.html&quot; title=&quot;Casque de mille feux&quot;&gt;Casque de Mille Feux&lt;/a&gt;, inflige des d&#233;g&#226;ts aux mort-vivants &#224; 9 m ou moins mais conf&#232;re une r&#233;sistance &#224; l’&#233;lectricit&#233; (plut&#244;t qu’au feu) de 30 au porteur et la propri&#233;t&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Foudre.html&quot; title=&quot;foudre (propri&#233;t&#233;)&quot;&gt;de foudre&lt;/a&gt; (plut&#244;t que &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Feu.html&quot; title=&quot;feu (propri&#233;t&#233;)&quot;&gt;de feu&lt;/a&gt;) aux armes qu’il manie.&lt;/td&gt;&lt;td&gt;125 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casque-De-Mille-Feux.html&quot; title=&quot;Casque de mille feux&quot;&gt;Casque de mille feux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Contient 100 pierres pr&#233;cieuses dont 4 types diff&#233;rents manifestant des effets magiques puissants en rapport avec le feu propres &#224; chaque type. Inflige des d&#233;g&#226;ts aux mort-vivants &#224; 9 m ou moins, conf&#232;re une r&#233;sistance au feu de 30 au porteur et la propri&#233;t&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Feu.html&quot; title=&quot;feu (propri&#233;t&#233;)&quot;&gt;de feu&lt;/a&gt; aux armes qu’il manie. Peut exploser sur le porteur s’il est br&#251;l&#233; par des flammes magiques.&lt;/td&gt;&lt;td&gt;125 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diad&#232;me-Des-Cieux.html&quot; title=&quot;Diad&#232;me des cieux&quot;&gt;Diad&#232;me des cieux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de parler le c&#233;leste, de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Mal.html&quot; title=&quot;D&#233;tection du Mal&quot;&gt;d&#233;tection du Mal&lt;/a&gt;&lt;/i&gt; &#224; volont&#233; et de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Don-Des-Langues.html&quot; title=&quot;Don des langues&quot;&gt;don des langues&lt;/a&gt;&lt;/i&gt; une fois par jour. Conf&#232;re un bonus de saintet&#233; de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans) contre les ext&#233;rieurs de sous-type Bien ou Mal et un bonus de +1 au &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; aux sorts du registre du Bien lanc&#233;s par le porteur. Conf&#232;re des effets suppl&#233;mentaires si le porteur poss&#232;de l’&lt;a class=&quot;pagelink&quot; href=&quot;Orbe-Des-Cieux.html&quot; title=&quot;Orbe des Cieux&quot;&gt;orbe des cieux&lt;/a&gt; et/ou le &lt;a class=&quot;pagelink&quot; href=&quot;Sceptre-Du-Paradis.html&quot; title=&quot;Sceptre du paradis&quot;&gt;sceptre du paradis&lt;/a&gt;. Un porteur d’alignement Mauvais subit des &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;Absorption d’&#233;nergie (Sur)&quot;&gt;niveaux n&#233;gatifs&lt;/a&gt; permanent tant qu’il ne retire pas le diad&#232;me.&lt;/td&gt;&lt;td&gt;150 000 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
